with metrics as (select *, first_value(browser, true) over w_part first_known_browser, last_value(country, true) over (partition by device, country order by started_at, id rows between unbounded preceding and current row) last_known_country, row_number() over w_running event_seq, last_value(country) ignore nulls over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) last_known_country_2, row_number() over (partition by month(started_at) order by started_at desc, id) row_seq from sessions where customer_id is not null window w_part as (partition by country, device order by started_at, id rows between unbounded preceding and current row), w_running as (order by started_at desc, id)) select id, customer_id, browser, first_known_browser, event_seq, last_known_country_2, row_seq, case when browser rlike '^(Edge|Firefox)$' then 'CORE' when browser rlike '^(Chrome|Safari)$' then 'GROUP_B' else 'OTHER_ZONE' end as browser_zone from metrics
